// Se busca la copia mas reciente y se comprueban tres cosas distintas.
// Las tres hacen falta, porque cada una falla de una forma propia:
//
//   1. QUE EXISTA UNA DE HOY. Un archivo de hace tres dias significa que
//      el servicio de copias dejo de correr y nadie se entero. Es el fallo
//      mas comun y el mas silencioso.
//   2. QUE NO ESTE VACIA. Una copia de 20 bytes es pg_dump fallando y
//      escribiendo el error en el archivo.
//   3. QUE EL GZIP ESTE INTEGRO (nodo siguiente). Un archivo truncado
//      pesa bien y no se puede restaurar.
//
// Lo que esto NO prueba es que la restauracion funcione. Eso solo lo
// prueba restaurar, y esta anotado en las limitaciones del punto 13.

const salida = $input.first().json.stdout || '';
const error = $input.first().json.stderr || '';

const lineas = salida.split('\n').filter((l) => l.includes('.sql.gz'));

if (lineas.length === 0) {
  return [{ json: {
    ok: false,
    motivo: 'NO HAY NINGUNA COPIA',
    detalle: `El directorio /copias no tiene archivos .sql.gz.${error ? ' Error: ' + error : ''}`,
    archivo: null,
  } }];
}

// ls -la: permisos, enlaces, duenio, grupo, tamano, fecha, nombre
const copias = lineas.map((l) => {
  const c = l.trim().split(/\s+/);
  return { bytes: Number(c[4]), fecha: c[5], ruta: c[6] };
}).filter((c) => Number.isFinite(c.bytes) && c.ruta);

copias.sort((a, b) => String(b.fecha).localeCompare(String(a.fecha)));
const ultima = copias[0];

const MINIMO_BYTES = 1024 * 100;           // 100 KB
const MAXIMA_EDAD_HORAS = 26;              // un dia mas margen

const edadHoras = (Date.now() - new Date(ultima.fecha).getTime()) / 3600000;

if (!Number.isFinite(edadHoras)) {
  return [{ json: { ok: false, motivo: 'FECHA ILEGIBLE', detalle: `No se pudo interpretar la fecha "${ultima.fecha}".`, archivo: ultima.ruta } }];
}
if (edadHoras > MAXIMA_EDAD_HORAS) {
  return [{ json: {
    ok: false,
    motivo: 'LA COPIA ESTA VIEJA',
    detalle: `La ultima copia es de hace ${edadHoras.toFixed(1)} h (${ultima.fecha}). El limite son ${MAXIMA_EDAD_HORAS} h. El servicio de copias no esta corriendo.`,
    archivo: ultima.ruta, bytes: ultima.bytes,
  } }];
}
if (ultima.bytes < MINIMO_BYTES) {
  return [{ json: {
    ok: false,
    motivo: 'LA COPIA ESTA VACIA O CASI',
    detalle: `${ultima.ruta} pesa ${ultima.bytes} bytes. Una copia real de esta base pesa cientos de megas: esto es pg_dump fallando y escribiendo el error adentro del archivo.`,
    archivo: ultima.ruta, bytes: ultima.bytes,
  } }];
}

return [{ json: {
  ok: true,
  archivo: ultima.ruta,
  bytes: ultima.bytes,
  megas: (ultima.bytes / 1048576).toFixed(1),
  fecha: ultima.fecha,
  edadHoras: edadHoras.toFixed(1),
  cantidad: copias.length,
} }];

const r = $input.first().json;
const datos = $('Revisar fecha y tamano').first().json;
const integro = String(r.stdout || '').includes('INTEGRO');

if (integro) {
  return [{ json: {
    ...datos,
    ok: true,
    resumen: `Copia correcta: ${datos.archivo}, ${datos.megas} MB, de hace ${datos.edadHoras} h. Hay ${datos.cantidad} copias guardadas.`,
  } }];
}

return [{ json: {
  ...datos,
  ok: false,
  motivo: 'EL ARCHIVO ESTA CORRUPTO',
  detalle: `gzip -t fallo sobre ${datos.archivo}. El archivo pesa ${datos.megas} MB y la fecha es correcta, pero no se puede descomprimir: no sirve para restaurar.`,
} }];
